<script setup lang="ts">
import {ref} from 'vue'
const items=[{id:'tokens',title:'Sample tokens',body:'Use the sample color, type and spacing tokens.'},{id:'behavior',title:'Sample behavior',body:'Keep changes tied to a clear local state.'},{id:'access',title:'Sample accessibility',body:'Keep visible labels, focus and reduced-motion support.'}]
const mode=ref('single'),variant=ref('bordered'),opened=ref<string[]>(['tokens'])
function toggle(id:string){opened.value=opened.value.includes(id)?opened.value.filter(x=>x!==id):mode.value==='single'?[id]:[...opened.value,id]}
function changeMode(){if(mode.value==='single')opened.value=opened.value.slice(0,1)}
function reset(){mode.value='single';variant.value='bordered';opened.value=['tokens']}
</script>
<template><section class="accordion-usage" aria-label="Accordion usage demonstration"><p>Fictitious local content. Opening a panel does not fetch or save data.</p><div class="options"><label>Open policy<select v-model="mode" @change="changeMode"><option>single</option><option>multiple</option></select></label><label>Accordion appearance<select v-model="variant"><option>bordered</option><option>flush</option></select></label><button type="button" @click="reset">Reset accordion</button></div><div class="panels" :class="variant"><section v-for="item in items" :key="item.id"><h3><button :id="`accordion-guide-trigger-${item.id}`" type="button" :aria-expanded="opened.includes(item.id)" :aria-controls="`accordion-guide-panel-${item.id}`" @click="toggle(item.id)">{{item.title}}<span aria-hidden="true">{{opened.includes(item.id)?'−':'+'}}</span></button></h3><div :id="`accordion-guide-panel-${item.id}`" :hidden="!opened.includes(item.id)" :aria-labelledby="`accordion-guide-trigger-${item.id}`" class="body"><p>{{item.body}}</p></div></section></div><p role="status">{{opened.length}} sample panels open. {{mode==='single'?'At most one; all may close.':'Multiple may stay open.'}}</p></section></template>
<style scoped>
.accordion-usage{padding:20px;margin:20px 0;border:1px solid var(--vp-c-divider);border-radius:12px}.options{display:flex;gap:14px;flex-wrap:wrap;align-items:end}label{display:flex;flex-direction:column;gap:8px}button,select{min-height:44px;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.panels{margin-top:24px;border:1px solid var(--vp-c-divider);border-radius:8px;overflow:hidden}.panels h3{margin:0;font-size:17px}.panels h3 button{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;text-align:left;border:0;border-radius:0;border-bottom:1px solid var(--vp-c-divider);transition:background 150ms ease-out}.panels h3 button[aria-expanded=true]{background:var(--vp-c-brand-soft)}.body{padding:4px 16px 14px}.body:not([hidden]){animation:accordion-enter 160ms ease-out}.panels.flush{border-left:0;border-right:0;border-radius:0}:focus-visible{outline:3px solid var(--vp-c-brand-1);outline-offset:-3px}@keyframes accordion-enter{from{opacity:.4;translate:0 3px}to{opacity:1;translate:0 0}}@media(prefers-reduced-motion:reduce){.body:not([hidden]){animation:none}.panels h3 button{transition:none}}
</style>
